'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { Download, ExternalLink, ArrowLeft, ShoppingBag } from 'lucide-react';
import { useWallet } from '@/context/WalletContext';
import { Purchase } from '@/lib/db';

export default function BuyerPurchasesPage() {
  const { walletAddress } = useWallet();
  const [purchases, setPurchases] = useState<Purchase[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    async function fetchMyPurchases() {
      setIsLoading(true);
      try {
        if (walletAddress) {
          const res = await fetch(`/api/purchases/me?buyerAddress=${encodeURIComponent(walletAddress)}`);
          if (res.ok) {
            const data = await res.json();
            setPurchases(data.purchases || []);
          }
        } else {
          setPurchases([]);
        }
      } catch (err) {
        console.error('Failed to fetch buyer purchases:', err);
      } finally {
        setIsLoading(false);
      }
    }
    fetchMyPurchases();
  }, [walletAddress]);

  return (
    <div className="ambient-bg-wash" style={{ minHeight: '100vh', padding: '40px 0 100px 0' }}>
      <div className="container" style={{ maxWidth: '800px' }}>
        <Link href="/" style={{ textDecoration: 'none', color: 'var(--text-secondary)', display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '0.9rem', marginBottom: '32px' }}>
          <ArrowLeft size={16} /> Back to Home
        </Link>

        {/* Header Image */}
        <div style={{
          width: '100%', maxHeight: '160px', height: '140px', borderRadius: '16px', overflow: 'hidden',
          marginBottom: '24px', boxShadow: 'var(--shadow-md)', border: '1px solid var(--border-light)'
        }} className="img-hover">
          <img src="/images/purchases_header_desk.jpg" alt="Purchases Library Header" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
        </div>

        <div style={{ marginBottom: '32px' }}>
          <div style={{ display: 'inline-block', backgroundColor: 'var(--bg-secondary)', padding: '4px 12px', borderRadius: '100px', marginBottom: '8px' }}>
            <span className="eyebrow" style={{ color: 'var(--text-secondary)', fontSize: '0.68rem' }}>MY DIGITAL LIBRARY</span>
          </div>
          <h1 style={{ fontSize: 'clamp(1.5rem, 4vw, 2.4rem)', marginBottom: '8px' }}>Purchased Digital Goods</h1>
          <p style={{ color: 'var(--text-secondary)' }}>
            All your on-chain verified downloads and signed receipts.
          </p>
        </div>

        {isLoading ? (
          <div style={{ padding: '60px', textAlign: 'center', color: 'var(--text-tertiary)' }}>
            Loading your digital library...
          </div>
        ) : purchases.length === 0 ? (
          <div className="card" style={{ padding: '60px 40px', textAlign: 'center' }}>
            <ShoppingBag size={40} color="var(--text-tertiary)" style={{ marginBottom: '16px' }} />
            <h3 style={{ fontSize: '1.3rem', marginBottom: '8px' }}>You haven't purchased anything yet</h3>
            <p style={{ color: 'var(--text-secondary)', marginBottom: '24px' }}>
              Browse creator storefronts on the Explore page and collect presets, templates, or guides.
            </p>
            <Link href="/explore" className="btn btn-lime">
              Explore Storefronts
            </Link>
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {purchases.map((item) => (
              <div key={item.txHash} className="card glow-hover" style={{ padding: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '16px' }}>
                <div>
                  <div className="font-mono" style={{ fontSize: '0.78rem', color: 'var(--accent-olive)', marginBottom: '4px' }}>
                    STOREFRONT: @{item.handle}
                  </div>
                  <h3 style={{ fontSize: '1.2rem', marginBottom: '6px' }}>{item.productTitle}</h3>
                  <div style={{ fontSize: '0.82rem', color: 'var(--text-tertiary)' }} className="font-mono">
                    Paid {item.amountNim ? `${item.amountNim.toLocaleString()} NIM` : `$${item.amountUsdt} USDT`} • Verified {new Date(item.verifiedAt).toLocaleDateString()}
                  </div>
                </div>

                <div style={{ display: 'flex', gap: '10px', alignItems: 'center', flexWrap: 'wrap' }}>
                  <a href={`https://raw.githubusercontent.com/nimiq/developer-center/main/README.md`} download target="_blank" rel="noreferrer" className="btn btn-lime btn-sm">
                    <Download size={16} /> Download Deliverable
                  </a>
                  <a href={`https://nimiq.watch/#${item.txHash}`} target="_blank" rel="noreferrer" className="btn btn-ghost btn-sm">
                    <ExternalLink size={16} /> NimiqHub Receipt
                  </a>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
